<script>
'use strict';
/* =========================================================================
   GALAGA clone - single file. Sections:
   1 canvas/scale  2 audio  3 sprites  4 input  5 starfield  6 state
   7 paths  8 enemies/formation  9 player  10 collisions  11 challenging
   12 update  13 render  14 fixed-timestep loop
   ========================================================================= */

/* ---------- 1. canvas & crisp scaling ---------- */
const W=224, H=288;                       // arcade resolution (3:4)
const cv=document.getElementById('c'), ctx=cv.getContext('2d');
ctx.imageSmoothingEnabled=false;
function resize(){
  const s=Math.max(1,Math.min(Math.floor(innerWidth/W),Math.floor(innerHeight/H)));
  cv.style.width=(W*s)+'px'; cv.style.height=(H*s)+'px';
}
addEventListener('resize',resize); resize();

/* ---------- 2. synthesized sound (Web Audio) ---------- */
let AC=null, master=null;
function initAudio(){                    // called on first key press
  if(AC) return;
  try{
    AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain(); master.gain.value=0.14; master.connect(AC.destination);
  }catch(e){}
}
function tone(f0,f1,dur,type,vol,delay){
  if(!AC||G.muted)return;
  const t=AC.currentTime+(delay||0);
  const o=AC.createOscillator(), g=AC.createGain();
  o.type=type||'square';
  o.frequency.setValueAtTime(Math.max(1,f0),t);
  if(f1) o.frequency.exponentialRampToValueAtTime(Math.max(1,f1),t+dur);
  g.gain.setValueAtTime(vol||0.3,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.connect(g); g.connect(master); o.start(t); o.stop(t+dur+0.02);
}
function noise(dur,vol,f0,f1){
  if(!AC||G.muted)return;
  const t=AC.currentTime, len=Math.floor(AC.sampleRate*dur);
  const buf=AC.createBuffer(1,len,AC.sampleRate), d=buf.getChannelData(0);
  for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
  const n=AC.createBufferSource(); n.buffer=buf;
  const f=AC.createBiquadFilter(); f.type='lowpass';
  f.frequency.setValueAtTime(f0||1500,t);
  if(f1) f.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+dur);
  const g=AC.createGain();
  g.gain.setValueAtTime(vol||0.4,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  n.connect(f); f.connect(g); g.connect(master); n.start(t);
}
const sShot   =()=>tone(900,180,0.09,'square',0.22);
const sHit    =()=>noise(0.16,0.35,1600,200);
const sBoom   =()=>{noise(0.3,0.4,900,80);tone(220,60,0.28,'sawtooth',0.18);};
