const sTracTick=()=>tone(520+(tick%2)*160,0,0.1,'sine',0.22);
const sCapture=()=>tone(180,760,0.55,'sawtooth',0.2);
const sJingle =()=>{const n=[196,247,294,392,330,294,247];n.forEach((f,i)=>tone(f,0,0.16,'square',0.25,i*0.15));};
const sExtra  =()=>{[523,659,784,1047].forEach((f,i)=>tone(f,0,0.1,'square',0.25,i*0.08));};
