/* ---------- 3. pixel-art sprites defined as data ---------- */
const PAL={W:'#ffffff',R:'#ff2a2a',Y:'#ffd24a',B:'#3b7bff',G:'#2ee62e',
           P:'#a24aff',C:'#59e6ff',O:'#ff8a1e'};
function mkSprite(rows,map){
  if(map) rows=rows.map(r=>r.replace(/[A-Z]/g,ch=>map[ch]||ch));
  const w=rows[0].length,h=rows.length;
  const c=document.createElement('canvas'); c.width=w; c.height=h;
  const g=c.getContext('2d');
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){
    const ch=rows[y][x]; if(ch!=='.'){g.fillStyle=PAL[ch]||'#fff';g.fillRect(x,y,1,1);}
  }
  return c;
}
const SPR={};
/* player fighter (faces up) */
SPR.player=mkSprite([
"......W......",
