/* BOSS GALAGA (green; blue/purple once hit) */
const BOSS_A=[
"GGG.......GGG",
"GGGG.GGG.GGGG",
".GGGGGGGGGGG.",
"GG.GGWWWGG.GG",
"GGGGWWBWWGGGG",
"GGGGWWWWWGGGG",
