SPR.boss=[mkSprite(BOSS_A),mkSprite(BOSS_B)];
SPR.bossHit=[mkSprite(BOSS_A,{G:'B',B:'P',W:'C'}),mkSprite(BOSS_B,{G:'B',B:'P',W:'C'})];
/* challenging-stage bird (purple bee) */
SPR.chal=[mkSprite(SPR.zako[0]?undefined:undefined)];
SPR.chal=[mkSprite([
"PP........PP","PPP.PPPP.PPP",".PPPYYYYPPP.","..PYYYYYYP..","...YYYYYY...",
"..PPYYYYPP..","..PPYYYYPP..","...YYYYYY...","....P..P....","............"]),
mkSprite([
"....PPPP....","...PPPPPP...","..PPYYYYPP..","PPP.YYYY.PPP","PPP.YYYY.PPP",
"..PPYYYYPP..","...YYYYYY...","....YYYY....",".....PP.....","............"])];
/* enemy explosion frames */
SPR.boom=[mkSprite([
"......Y......",
"....Y.W.Y....",
"...Y.WWW.Y...",
"..Y.WWWWW.Y..",
"...Y.WWW.Y...",
"....Y.W.Y....",
"......Y......"]),mkSprite([
"..R...O...R..","...O.R...O...","..R.WWW.O..R.",".O.WWWWW..O..",
"...WWWWW.R...",".R..WWW...O.R","..O.WWW.R..O.","...O.R...O...","..R...O...R.."]),mkSprite([
".R...Y...R.Y.","...Y.....Y...","..R..Y....R..",".Y.....R...Y.",
"...R....Y....",".Y...R....R.Y","..R....Y..R..","...Y.....Y...",".R...Y...R.Y."])];
/* player explosion (procedural ring frames) */
function mkPBoom(r,cols){
  const c=document.createElement('canvas'); c.width=25; c.height=25;
  const g=c.getContext('2d');
  for(let a=0;a<Math.PI*2;a+=0.22){
    g.fillStyle=cols[(Math.round(a*7))%cols.length];
    const x=12+Math.cos(a)*r+(Math.random()*3-1.5), y=12+Math.sin(a)*r+(Math.random()*3-1.5);
    g.fillRect(Math.round(x),Math.round(y),2,2);
  }
  for(let i=0;i<12;i++){
    g.fillStyle=cols[i%cols.length];
    g.fillRect(Math.round(Math.random()*23),Math.round(Math.random()*23),2,2);
  }
  return c;
}
SPR.pboom=[mkPBoom(4,['#ffffff','#ffd24a']),mkPBoom(8,['#ffd24a','#ff8a1e']),mkPBoom(12,['#ff8a1e','#ff2a2a'])];
/* stage badges (flags) */
function mkFlag(hex){
  return mkSprite([
  "W.........",
  "WFFFFFFFF.",
  "WFFFFFFFF.",
  "WFFFF.....",
  "WFFF......",
  "W.........",
  "W.........",
  "W........."],{F:'Q'});
}
/* build flags with explicit colors (mkSprite maps only palette letters, so patch) */
function mkFlagC(hex){
  const rows=["WFFFFFFFF.","WFFFFFFFF.","WFFFF.....","WFFF......"];
  const c=document.createElement('canvas'); c.width=10;c.height=9;
  const g=c.getContext('2d');
  g.fillStyle='#ffffff'; g.fillRect(0,0,1,9);
  for(let y=0;y<rows.length;y++)for(let x=0;x<rows[y].length;x++)
    if(rows[y][x]==='F'){g.fillStyle=hex;g.fillRect(x+1,y,1,1);}
  return c;
}
const FLAGS=[[50,mkFlagC('#a24aff')],[20,mkFlagC('#ffd24a')],[10,mkFlagC('#2ee62e')],[5,mkFlagC('#3b7bff')],[1,mkFlagC('#ff2a2a')]];

/* ---------- 4. input ---------- */
const keys={};
addEventListener('keydown',e=>{
  initAudio();
  if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key)) e.preventDefault();
  if(e.repeat) return;
  keys[e.code]=true;
  if(e.code==='KeyM') G.muted=!G.muted;
  if(e.code==='KeyP'&&(G.mode==='play'||G.mode==='challenge')) G.paused=!G.paused;
  if(e.code==='Enter'&&G.mode==='title') startGame();
});
addEventListener('keyup',e=>{keys[e.code]=false;});

/* ---------- 5. scrolling twinkling starfield ---------- */
const stars=[];
for(let i=0;i<70;i++) stars.push({x:Math.random()*W,y:Math.random()*H,
  s:0.15+Math.random()*0.5, c:['#ffffff','#9bc4ff','#59e6ff','#ffd24a'][i%4], p:Math.random()*6.28});
function updateStars(){for(const s of stars){s.y+=s.s;if(s.y>=H){s.y=0;s.x=Math.random()*W;}}}

/* ---------- 6. game state ---------- */
let enemies=[],bullets=[],pshots=[],booms=[],bonusShips=[];
let tick=0,swayT=0,diveTimer=0,entryQueue=[],formationFull=false,stageClearT=0,readyT=0;
let beamBoss=null,CH=null;
const G={mode:'title',modeT:0,score:0,hi:0,lives:2,stage:1,nextExtra:20000,
         shots:0,hits:0,paused:false,muted:false};
try{G.hi=parseInt(localStorage.getItem('galaga_hi')||'0')||0;}catch(e){}
function saveHi(){try{localStorage.setItem('galaga_hi',''+G.hi);}catch(e){}}

const P={x:112,y:262,state:'off',dual:false,inv:0,respawnT:0,pullX:0,pullY:0};
/* P.state: 'off','ready','fly','pull','dead' */

function isChallenging(s){return s===3||(s-3)%4===0;}
function startGame(){
  G.score=0;G.lives=2;G.stage=1;G.nextExtra=20000;G.shots=0;G.hits=0;G.paused=false;
  beginStage();
}
function beginStage(){
  enemies=[];bullets=[];pshots=[];booms=[];bonusShips=[];entryQueue=[];
  formationFull=false;stageClearT=0;beamBoss=null;
  G.mode='intro';G.modeT=110;
  if(isChallenging(G.stage)){ CH={wave:0,spawnT:0,spawned:0,waveHits:0,total:0,bonus:0,phase:0,phaseT:0}; }
  else buildEntryQueue();
}
function gameOver(){G.mode='gameover';G.modeT=170;}

/* ---------- 7. curved paths (chains of cubic Béziers) ---------- */
function cubic(p0,p1,p2,p3,t){
  const u=1-t,a=u*u*u,b=3*u*u*t,c=3*u*t*t,d=t*t*t;
  return {x:a*p0.x+b*p1.x+c*p2.x+d*p3.x, y:a*p0.y+b*p1.y+c*p2.y+d*p3.y,
    ang:Math.atan2(3*u*u*(p1.y-p0.y)+6*u*t*(p2.y-p1.y)+3*t*t*(p3.y-p2.y),
                   3*u*u*(p1.x-p0.x)+6*u*t*(p2.x-p1.x)+3*t*t*(p3.x-p2.x))};
}
function segLen(s){ // approximate length by sampling
  let L=0,px=s[0].x,py=s[0].y;
  for(let i=1;i<=12;i++){const p=cubic(s[0],s[1],s[2],s[3],i/12);
    L+=Math.hypot(p.x-px,p.y-py);px=p.x;py=p.y;}
  return L;
}
function buildPath(segs){
  return segs.map(s=>({s,len:segLen(s)}));
}
/* entry routine 1: from top, loop, exit right (dir=+1) or left (dir=-1) */
function pathTopLoop(dir){
  const p0={x:112,y:-20},p1={x:112,y:50},p2={x:112,y:85},p3={x:112,y:112};
  const q0=p3,q1={x:112+45*dir,y:82},q2={x:112+55*dir,y:150},q3={x:112+12*dir,y:162};
  const r0=q3,r1={x:112-25*dir,y:185},r2={x:112+95*dir,y:120},r3={x:dir>0?W+40:-40,y:88};
  return buildPath([[p0,p1,p2,p3],[q0,q1,q2,q3],[r0,r1,r2,r3]]);
}
/* entry routine 2: from one side, arc across, exit the other side */
function pathSide(side){ // side=+1 enters from left
  const p0={x:side>0?-40:W+40,y:55},p1={x:112-40*side,y:30},p2={x:112+40*side,y:130},p3={x:112,y:150};
  const q0=p3,q1={x:112+40*side,y:170},q2={x:112+70*side,y:100},q3={x:112+20*side,y:95};
  const r0=q3,r1={x:112-30*side,y:88},r2={x:side>0?W+60:-60,y:140},r3={x:side>0?W+40:-40,y:190};
  return buildPath([[p0,p1,p2,p3],[q0,q1,q2,q3],[r0,r1,r2,r3]]);
}
/* challenging-stage routine: enter from side, figure loop, leave off the other side */
function pathChal(side){
  const p0={x:side>0?-40:W+40,y:60},p1={x:60,y:40},p2={x:164,y:60},p3={x:112,y:110};
  const q0=p3,q1={x:60,y:160},q2={x:164,y:160},q3={x:112,y:110}; // loop
  const r0=q3,r1={x:164,y:60},r2={x:side>0?W+60:-60,y:120},r3={x:side>0?W+40:-40,y:200};
  return buildPath([[p0,p1,p2,p3],[q0,q1,q2,q3],[r0,r1,r2,r3]]);
}
/* dive path: one loop then a swoop toward the player */
function divePath(e){
  const dir=e.x<W/2?1:-1;
  const p0={x:e.x,y:e.y};
  const p1={x:e.x+45*dir,y:e.y-30},p2={x:e.x+55*dir,y:e.y+45},p3={x:e.x+15*dir,y:e.y+55};
  const tx=Math.max(14,Math.min(W-14,P.x+(Math.random()*60-30)));
  const q0=p3,q1={x:e.x-30*dir,y:e.y+90},q2={x:tx+40*dir,y:e.y+130},q3={x:tx,y:H+26};
  return buildPath([[p0,p1,p2,p3],[q0,q1,q2,q3]]);
}
function advancePath(e,speed){
  const path=e.path;
  if(e.seg>=path.length) return true;
  e.t+=speed/path[e.seg].len;
  while(e.t>=1&&e.seg<path.length-1){e.t-=1;e.seg++;}
  const s=path[Math.min(e.seg,path.length-1)].s;
  const p=cubic(s[0],s[1],s[2],s[3],Math.min(e.t,1));
  e.x=p.x;e.y=p.y;e.ang=p.ang;
  return e.seg>=path.length-1&&e.t>=1;
}

/* ---------- 8. enemies & formation ---------- */
/* formation slots: row0 = 4 boss (cols 3-6), rows1-2 = 8 goei each (cols 1-8),
   rows3-4 = 10 zako each (cols 0-9)  -> 40 enemies */
function buildEntryQueue(){
  const list=[];
  for(let c=3;c<=6;c++) list.push({type:'boss',r:0,c});
  for(let r=1;r<=2;r++)for(let c=1;c<=8;c++) list.push({type:'goei',r,c});
  for(let r=3;r<=4;r++)for(let c=0;c<=9;c++) list.push({type:'zako',r,c});
  const paths=[()=>pathTopLoop(1),()=>pathTopLoop(-1),()=>pathSide(1),()=>pathSide(-1),()=>pathTopLoop(1)];
  for(let g=0;g<5;g++){
    const members=list.slice(g*8,g*8+8);
    entryQueue.push({t:g*105,members:members.map((m,i)=>({m,t:i*6})),
                     pathFn:paths[g],pathIdx:0});
  }
}
function slotPos(e){
  const sway=Math.sin(swayT*0.02)*(formationFull?5:9);
  const sc=formationFull?1+0.06*Math.sin(swayT*0.012):1;
  const bx=112+(e.slot.c-4.5)*16, by=40+e.slot.r*16;
  return {x:112+(bx-112)*sc+sway, y:66+(by-66)*sc};
}
function spawnEnemy(type,slot,pathFn){
  const e={type,hp:type==='boss'?2:1,state:'entry',slot,path:pathFn(),seg:0,t:0,
           x:112,y:-20,ang:Math.PI/2,escorts:null,carrier:null,mode:null,
           beamT:0,beamY:0,cd:0,hs:null,hx:0,hy:0};
  enemies.push(e);return e;
}
function fireBullet(x,y,aim){
  let vx=0,vy=2.3;
  if(aim){const dx=P.x-x,dy=P.y-y,d=Math.hypot(dx,dy)||1;vx=dx/d*2.3;vy=dy/d*2.3;}
  bullets.push({x,y,vx,vy});
}
function updateEnemy(e){
  const fireP=0.0012*(1+G.stage*0.35);
  if(e.state==='entry'){
    if(advancePath(e,1.7)){e.state='toSlot';}
    if(e.type!=='chal'&&e.y>15&&e.y<190&&Math.random()<fireP) fireBullet(e.x,e.y+6,false);
    if(e.type==='chal'&&(e.x<-35||e.x>W+35||e.y>H+35)) e.dead=true;
  }else if(e.state==='toSlot'||e.state==='return'){
    const sp=slotPos(e),dx=sp.x-e.x,dy=sp.y-e.y,d=Math.hypot(dx,dy);
    const v=e.state==='return'?2.4:2.2;
    if(d<v){e.x=sp.x;e.y=sp.y;e.state='formation';}
    else{e.x+=dx/d*v;e.y+=dy/d*v;}
    e.ang=Math.PI/2;
    if(e.state==='return'&&e.type!=='chal'&&Math.random()<fireP*0.5) fireBullet(e.x,e.y+6,false);
  }else if(e.state==='formation'){
    const sp=slotPos(e);e.x=sp.x;e.y=sp.y;e.ang=Math.PI/2;
    if(e.type!=='chal'&&Math.random()<fireP*0.35&&G.stage>1) fireBullet(e.x,e.y+6,Math.random()<0.5);
  }else if(e.state==='dive'){
    if(advancePath(e,2.0)||e.y>H+16){
      if(e.type==='chal'){e.dead=true;return;}
      e.state='return';e.x=slotPos(e).x+(Math.random()*40-20);e.y=-14;
    }
    if(e.type!=='chal'&&Math.random()<0.004*(1+G.stage*0.3)) fireBullet(e.x,e.y+6,true);
  }else if(e.state==='diveStop'){        // boss descending to beam position
    e.y+=1.6; e.ang=Math.PI/2;
    if(e.y>=e.beamY){e.state='beam';e.beamT=0;}
    if(Math.random()<0.006) fireBullet(e.x,e.y+6,true);
  }else if(e.state==='beam'){            // projecting tractor beam
    e.beamT++; sTracTick();
    if(e.beamT>210){e.state='return';}
  }else if(e.state==='escort'){          // fly in V around boss
    const b=e.carrier;
    e.x=b.x+e.hx; e.y=b.y+e.hy; e.ang=Math.PI/2;
    if(b.dead||b.state==='return'||b.state==='beam'){e.carrier=null;e.state='dive';e.path=divePath(e);e.seg=0;e.t=0;}
  }else if(e.state==='captive'){         // held fighter following its boss
    const b=e.carrier;
    const off=b.state==='beam'?18:14;
    e.x=b.x; e.y=b.y-off; e.ang=Math.PI/2;
    if((b.state==='dive'||b.state==='diveStop'||b.state==='beam')&&Math.random()<0.008)
      fireBullet(e.x,e.y+6,true);
  }else if(e.state==='freed'){           // freed fighter flying down to dock
    e.y+=1.6;
    if(P.state==='fly'){const dx=P.x-e.x;e.x+=Math.max(-2,Math.min(2,dx*0.1));}
    e.ang=Math.PI/2;
