  if(!inForm.length)return;
  const bosses=inForm.filter(e=>e.type==='boss');
  let e;
  if(bosses.length&&Math.random()<0.35) e=bosses[Math.floor(Math.random()*bosses.length)];
  else e=inForm[Math.floor(Math.random()*inForm.length)];
  if(e.type==='boss'){
    const hasCap=enemies.some(c=>c.type==='cap'&&c.carrier===e);
